import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";

export default function ListarUsuarios() {
  const [usuarios, setUsuarios] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    carregarUsuarios();
  }, []);

  const carregarUsuarios = () => {
    axios.get("http://localhost:3001/usuarios")
      .then(res => setUsuarios(res.data))
      .catch(err => console.error("Erro ao carregar usuários:", err));
  };

  const excluirUsuario = async (id) => {
    const confirmar = window.confirm("Tem certeza que deseja excluir este usuário?");
    if (!confirmar) return;

    try {
      await axios.delete(`http://localhost:3001/usuarios/${id}`);
      carregarUsuarios(); // Atualiza a lista
    } catch (error) {
      console.error("Erro ao excluir usuário:", error);
      alert("Erro ao excluir usuário.");
    }
  };

  return (
    <div className="container mt-5">
      {/* Título e botão de cadastro */}
      <div className="d-flex justify-content-between align-items-center mb-4">
        <h3 className="fw-bold">Perfis de Usuário</h3>
        <button className="btn btn-success" onClick={() => navigate("/cadastrar")}>
          Cadastrar Novo
        </button>
      </div>

      {/* Tabela */}
      <div className="row justify-content-center">
        <div className="col-md-10">
          <table className="table table-hover text-center align-middle border rounded shadow">
            <thead className="table-primary">
              <tr>
                <th>Nome</th>
                <th>Foto</th>
                <th>Ações</th>
              </tr>
            </thead>
            <tbody>
              {usuarios.map((user) => (
                <tr key={user.id}>
                  <td className="fw-semibold">{user.nome}</td>
                  <td>
                    {user.imagem ? (
                      <img
                        src={`http://localhost:3001${user.imagem}`}
                        alt="Foto"
                        style={{
                          width: 50,
                          height: 50,
                          borderRadius: "50%",
                          objectFit: "cover",
                          border: "2px solid #dee2e6"
                        }}
                      />
                    ) : (
                      "Sem foto"
                    )}
                  </td>
                  <td>
                    <button
                      className="btn btn-outline-info btn-sm me-2"
                      onClick={() => navigate(`/usuarios/${user.id}`)}
                    >
                      <i className="bi bi-eye"></i>
                    </button>
                    <button
                      className="btn btn-outline-warning btn-sm me-2"
                      onClick={() => navigate(`/editar/${user.id}`)}
                    >
                      <i className="bi bi-pencil"></i>
                    </button>
                    <button
                      className="btn btn-outline-danger btn-sm"
                      onClick={() => excluirUsuario(user.id)}
                    >
                      <i className="bi bi-trash"></i>
                    </button>
                  </td>
                </tr>
              ))}
              {usuarios.length === 0 && (
                <tr>
                  <td colSpan="3" className="text-muted">Nenhum usuário cadastrado.</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}
